"""RoboPaint: camera-calibrated, pressure-modulated lengthwise brush strokes."""
import sys, json, time, pathlib
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=pathlib.Path('/app/output'); Z=.0202; SCALE=.227185/1024
class Painter:
 def __init__(self):
  self.r=Robot(); self.o=self.r.get_obs(cameras=[]); self.pose=np.array(self.o.meta['proprio']['now'][7:14]); self.quat=np.array([0.,1.,0.,0.]); self.serial=int(self.o.meta['calls']); self.buffer=[]
 def flush(self,cameras=None):
  if not self.buffer:return
  a=np.array(self.buffer); self.buffer=[]
  for i in range(0,len(a),180):
   self.serial+=1
   np.save(OUT/f'actions_{self.serial:04d}.npy',a[i:i+180])
   before=self.r.status()
   try: res=self.r.submit('ee_pose',a[i:i+180],dt=.05,cameras=cameras or [],video='none')
   except Exception:
    print('SERVICE ERROR',self.r.wait_ready(), 'before',before,flush=True); raise
   (OUT/f'meta_{self.serial:04d}.json').write_text(json.dumps(res.meta))
   if res.meta.get('plan'): print('plan',res.meta['plan'],flush=True)
   print('call',self.serial,'steps',res.meta.get('control_steps'),'left',res.meta.get('time_left_s'),flush=True)
 def move(self,xyz,speed=.06,hold=0):
  target=np.r_[xyz,self.quat]; n=max(1,int(np.ceil(np.linalg.norm(target[:3]-self.pose[:3])/speed/.05)))
  self.buffer.extend(np.linspace(self.pose,target,n+1)[1:]); self.buffer.extend([target.copy()]*int(hold/.05)); self.pose=target
 def dip(self):
  self.move([*self.pose[:2],.075]); self.move([-.1,.15,.075]); self.move([-.1,.15,.025],.025,hold=.5); self.move([-.1,.15,.075],.03); self.flush()
 def park(self):
  self.move([*self.pose[:2],.075]); self.move([-.1,.15,.09]); self.flush()
 def observe(self,name):
  o=self.r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam'],depth=True); o.save(str(OUT/name))
  for c,a in o.last.items(): Image.fromarray(a).save(OUT/f'{name}_{c}.png')
  return o
 def practice_line(self,u,v,u2,v2,depth,speed=.012):
  def xyz(u,v,z):return [-.1+(512-v)*SCALE,-.1856+(224-u)*SCALE,z]
  self.move(xyz(u,v,.055)); self.move(xyz(u,v,Z-depth),.012,hold=.25); self.move(xyz(u2,v2,Z-depth),speed,hold=.2); self.move(xyz(u2,v2,.055),.015);self.flush()
if __name__=='__main__':
 p=Painter(); cmd=sys.argv[1]
