  p.dip()
  for i,d in enumerate([.001,.002,.003,.004,.006,.008,.010,.013]):
   p.practice_line(65,90+i*110,350,90+i*110,d)
  p.park();p.observe('calibration')
 elif cmd=='observe':p.park();p.observe('current')
